import React from "react";
import { AbsoluteFill, useCurrentFrame, interpolate, Easing } from "remotion";
import { BRAND } from "../../theme";

export const fps = 25;
export const durationInFrames = 84;

// Schematic frame — 1:1 (2160x2160) variant of the MCP launch frame.
// Outer rectangle (verticals + horizontals) traces corner-to-corner, then the
// two dashed inner guides reveal, then four "+" registration marks pop at the
// corners. Holds, then reverses in 23 frames.
//
// NOTE: No background fill — root AbsoluteFill is transparent so this scene
// composites cleanly over whatever sits beneath it.

const ORANGE = BRAND.colors.orange;
const STROKE_THIN = 2.81984;
const STROKE_PLUS = 8.45953;

const EASE = Easing.bezier(0.4, 0, 0.2, 1);

const VERT_LEN = 2160;
const HORIZ_LEN = 3396.96;
const DASH_LEN = 3001.54;

const ENTRY_VERT = [0, 7] as const;
const ENTRY_HORIZ = [7, 14] as const;
const ENTRY_DASH = [14, 22] as const;

const EXIT_DASH = [61, 69] as const;
const EXIT_HORIZ = [69, 76] as const;
const EXIT_VERT = [76, 84] as const;

const POP_V_CORNERS = 7;
const POP_H_CORNERS = 14;
const FADE_H_CORNERS = 66;
const FADE_V_CORNERS = 73;
const POP_DUR = 3;
const FADE_DUR = 3;

function reveal(
  frame: number,
  entry: readonly [number, number],
  exit: readonly [number, number],
  length: number,
): number {
  if (frame >= exit[0]) {
    return interpolate(frame, [exit[0], exit[1]], [length, 0], {
      easing: EASE,
      extrapolateLeft: "clamp",
      extrapolateRight: "clamp",
    });
  }
  return interpolate(frame, [entry[0], entry[1]], [0, length], {
    easing: EASE,
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });
}

function plusVis(frame: number, popAt: number, fadeAt: number): number {
  if (frame >= fadeAt) {
    return interpolate(frame, [fadeAt, fadeAt + FADE_DUR], [1, 0], {
      easing: EASE,
      extrapolateLeft: "clamp",
      extrapolateRight: "clamp",
    });
  }
  return interpolate(frame, [popAt, popAt + POP_DUR], [0, 1], {
    easing: Easing.out(Easing.cubic),
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });
}

export default function MCPLaunchFrame() {
  const frame = useCurrentFrame();

  const leftVertH = reveal(frame, ENTRY_VERT, EXIT_VERT, VERT_LEN);
  const rightVertH = reveal(frame, ENTRY_VERT, EXIT_VERT, VERT_LEN);
  const topHorizW = reveal(frame, ENTRY_HORIZ, EXIT_HORIZ, HORIZ_LEN);
  const bottomHorizW = reveal(frame, ENTRY_HORIZ, EXIT_HORIZ, HORIZ_LEN);
  const topDashW = reveal(frame, ENTRY_DASH, EXIT_DASH, DASH_LEN);
  const bottomDashW = reveal(frame, ENTRY_DASH, EXIT_DASH, DASH_LEN);

  const plusBL = plusVis(frame, POP_V_CORNERS, FADE_V_CORNERS);
  const plusTR = plusVis(frame, POP_V_CORNERS, FADE_V_CORNERS);
  const plusTL = plusVis(frame, POP_H_CORNERS, FADE_H_CORNERS);
  const plusBR = plusVis(frame, POP_H_CORNERS, FADE_H_CORNERS);

  return (
    <AbsoluteFill>
      <svg
        viewBox="0 0 2160 2160"
        width="100%"
        height="100%"
        preserveAspectRatio="xMidYMid meet"
        xmlns="http://www.w3.org/2000/svg"
      >
        <defs>
          <clipPath id="mcp-clip-left-vert">
            <rect x={186.5} y={0} width={5} height={leftVertH} />
          </clipPath>
          <clipPath id="mcp-clip-right-vert">
            <rect x={1951.5} y={VERT_LEN - rightVertH} width={5} height={rightVertH} />
          </clipPath>
          <clipPath id="mcp-clip-top-horiz">
            <rect x={3378.17 - topHorizW} y={158} width={topHorizW} height={5} />
          </clipPath>
          <clipPath id="mcp-clip-bottom-horiz">
            <rect x={-18.7861} y={1994} width={bottomHorizW} height={5} />
          </clipPath>
          <clipPath id="mcp-clip-top-dash">
            <rect x={-420.155} y={700} width={topDashW} height={5} />
          </clipPath>
          <clipPath id="mcp-clip-bottom-dash">
            <rect x={2581.38 - bottomDashW} y={1455.5} width={bottomDashW} height={5} />
          </clipPath>
        </defs>

        <path
          d="M188.93 0L188.93 2160"
          stroke={ORANGE}
          strokeWidth={STROKE_THIN}
          fill="none"
          clipPath="url(#mcp-clip-left-vert)"
        />
        <path
          d="M1954.15 0L1954.15 2160"
          stroke={ORANGE}
          strokeWidth={STROKE_THIN}
          fill="none"
          clipPath="url(#mcp-clip-right-vert)"
        />
        <path
          d="M-18.7861 160.731L3378.17 160.732"
          stroke={ORANGE}
          strokeWidth={STROKE_THIN}
          fill="none"
          clipPath="url(#mcp-clip-top-horiz)"
        />
        <path
          d="M-18.7861 1996.45L3378.17 1996.45"
          stroke={ORANGE}
          strokeWidth={STROKE_THIN}
          fill="none"
          clipPath="url(#mcp-clip-bottom-horiz)"
        />

        <path
          d="M2581.38 702.141L-420.155 702.14"
          stroke={ORANGE}
          strokeWidth={STROKE_THIN}
          strokeDasharray="18.03 18.03"
          fill="none"
          clipPath="url(#mcp-clip-top-dash)"
        />
        <path
          d="M2581.38 1457.86L-420.155 1457.86"
          stroke={ORANGE}
          strokeWidth={STROKE_THIN}
          strokeDasharray="18.03 18.03"
          fill="none"
          clipPath="url(#mcp-clip-bottom-dash)"
        />

        <g
          opacity={plusTL}
          transform={`translate(189.801 161.603) scale(${plusTL}) translate(-189.801 -161.603)`}
        >
          <path
            d="M189.801 135.353V187.883M216.081 161.603L163.551 161.603"
            stroke={ORANGE}
            strokeWidth={STROKE_PLUS}
            fill="none"
          />
        </g>
        <g
          opacity={plusTR}
          transform={`translate(1955.02 161.526) scale(${plusTR}) translate(-1955.02 -161.526)`}
        >
          <path
            d="M1955.02 135.275V187.806M1981.3 161.526L1928.77 161.526"
            stroke={ORANGE}
            strokeWidth={STROKE_PLUS}
            fill="none"
          />
        </g>
        <g
          opacity={plusBL}
          transform={`translate(189.801 1997.32) scale(${plusBL}) translate(-189.801 -1997.32)`}
        >
          <path
            d="M189.801 1971.07V2023.6M216.081 1997.32L163.551 1997.32"
            stroke={ORANGE}
            strokeWidth={STROKE_PLUS}
            fill="none"
          />
        </g>
        <g
          opacity={plusBR}
          transform={`translate(1955.02 1997.24) scale(${plusBR}) translate(-1955.02 -1997.24)`}
        >
          <path
            d="M1955.02 1970.99V2023.52M1981.3 1997.24L1928.77 1997.24"
            stroke={ORANGE}
            strokeWidth={STROKE_PLUS}
            fill="none"
          />
        </g>
      </svg>
    </AbsoluteFill>
  );
}
